(541939, 54610, 11440, '<td valign="top">good idea and fun too!</td>', 'good idea and fun too!', '2004-01-14 04:36:09.000000', NULL, 1),
(541940, 55133, 11440, '<td valign="top">cool effect</td>', 'cool effect', '2004-01-14 04:36:43.000000', NULL, 1),
(541942, 54632, 12802, '<td valign="top">Excellent idea, on one hand I''m thinking that the flower isn''t a good addition, but then I think it''s good that there is something else there other than just the feet.  8</td>', 'Excellent idea, on one hand I''m thinking that the flower isn''t a good addition, but then I think it''s good that there is something else there other than just the feet.  8', '2004-01-14 04:37:18.000000', NULL, 1),
