(546931, 54720, 7800, '<td valign="top">Cool! I hope you write about how you did this shot. Very vey nice.</td>', 'Cool! I hope you write about how you did this shot. Very vey nice.', '2004-01-17 17:17:13.000000', NULL, 1),
(546932, 54303, 7800, '<td valign="top">Wow! Fabulous color. Nice!</td>', 'Wow! Fabulous color. Nice!', '2004-01-17 17:17:36.000000', NULL, 1),
