(547214, 54857, 7810, '<td valign="top">nice b&amp;w ...great for the challenge</td>', 'nice b&w ...great for the challenge', '2004-01-17 23:43:22.000000', NULL, 1),
(547215, 55116, 15164, '<td valign="top">Composition is perfect. Contrast of color with gray tones works great. Great shot.</td>', 'Composition is perfect. Contrast of color with gray tones works great. Great shot.', '2004-01-17 23:43:24.000000', NULL, 1),
(547216, 55120, 7810, '<td valign="top">nice macro...great composition</td>', 'nice macro...great composition', '2004-01-17 23:43:50.000000', NULL, 1),
(547217, 54734, 12160, '<td valign="top">I like the originality of this photo. Great shot.</td>', 'I like the originality of this photo. Great shot.', '2004-01-17 23:44:30.000000', NULL, 1),
