(549870, 54848, 11457, '<td valign="top">X-actly 10 ;)</td>', 'X-actly 10 ;)', '2004-01-20 04:19:34.000000', NULL, 1),
(549871, 54225, 11457, '<td valign="top">Nice idea and realization. Love the fish-eye appearence of the reflected image. Wonderful composition. 10.</td>', 'Nice idea and realization. Love the fish-eye appearence of the reflected image. Wonderful composition. 10.', '2004-01-20 04:23:01.000000', NULL, 1),
(549872, 55014, 11457, '<td valign="top">I like the soft appearance of the horizon. Compositionally very interesting.</td>', 'I like the soft appearance of the horizon. Compositionally very interesting.', '2004-01-20 04:24:56.000000', NULL, 1),
(549875, 54959, 11457, '<td valign="top">The narrow depth of field really "pinpoints" the location. Nice idea!</td>', 'The narrow depth of field really "pinpoints" the location. Nice idea!', '2004-01-20 04:29:10.000000', NULL, 1),
(549876, 54160, 16248, '<td valign="top">nice photo</td>', 'nice photo', '2004-01-20 04:47:32.000000', NULL, 1),
