(550178, 54837, 5532, '<td valign="top">Good creative photo</td>', 'Good creative photo', '2004-01-20 10:16:07.000000', NULL, 1),
(550184, 54485, 5532, '<td valign="top">Very nice photo.  The colors are vibrant and help make this a good image.</td>', 'Very nice photo.  The colors are vibrant and help make this a good image.', '2004-01-20 10:18:29.000000', NULL, 1),
