(550192, 54619, 5532, '<td valign="top">Interesting shot.  Good choice to use black and white</td>', 'Interesting shot.  Good choice to use black and white', '2004-01-20 10:22:07.000000', NULL, 1),
(550195, 54604, 15345, '<td valign="top">Nice subject, but not sure what the point of view is...</td>', 'Nice subject, but not sure what the point of view is...', '2004-01-20 10:22:31.000000', NULL, 1),
